(()=>{const el=id=>document.getElementById(id),n=id=>Number(el(id).value)||0,f=(x,d=1)=>new Intl.NumberFormat('en-IE',{maximumFractionDigits:d}).format(x);function refresh(){const systems=n('calc-labs')*n('calc-hplc-count'),v=systems*n('calc-flow')*60*n('calc-hours-day')*n('calc-days-week')*n('calc-weeks-year')/1000,h=n('prep-hours')*n('calc-labs')*n('calc-weeks-year'),m=v*n('calc-solvent-cost'),d=v*n('calc-disposal-cost'),l=h*(n('prep-rate')/Number(document.getElementById('prep-paid-hours').value)),money=x=>'€'+f(x,2),labour=n('prep-hours')&&(n('prep-rate')/Number(document.getElementById('prep-paid-hours').value)),vals={systems:f(systems,0),litres:f(v)+' L/year',monthly:f(v/12)+' L/month',waste:f(v)+' L/year · ≈ '+f(v/1000,2)+' t/year',material:money(m),hours:n('prep-hours')?f(h)+' person-hours/year':'Enter preparation hours',labour:labour?money(l):'Enter hours and annual salary',preptotal:money(m+l)+(labour?'':' + labour not entered'),disposal:money(d),production:f(v*3.69/1000,2)+' t CO₂e/year',treatment:f(v*1.57/1000,2)+' t CO₂e/year',cash:money(m+d),total:money(m+d+l)+(labour?'':' + labour not entered'),carbon:f(v*5.26/1000,2)+' t CO₂e/year'};document.querySelectorAll('[data-stage]').forEach(e=>e.textContent=vals[e.dataset.stage]);}document.addEventListener('resolve-model',refresh);['prep-hours','prep-rate','prep-reduction'].forEach(id=>el(id).addEventListener('input',refresh));el('calc-reset').addEventListener('click',refresh);refresh();})();